CREATE TABLE private_note_attachment (id UUID PRIMARY KEY DEFAULT uuid_v7(),note_id UUID NOT NULL,vault_id UUID NOT NULL,owner_id UUID NOT NULL,attachment_id UUID NOT NULL,encrypted_file_name TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),FOREIGN KEY(note_id) REFERENCES private_note(id),FOREIGN KEY(vault_id) REFERENCES private_vault(id),FOREIGN KEY(attachment_id) REFERENCES attachment(id),UNIQUE(note_id,attachment_id)); CREATE INDEX idx_private_note_attachment ON private_note_attachment(note_id,created_at);
